package branchroom

import (
	"context"
	"errors"

	branchroom_model "gitea.dev/models/branchroom"
	"gitea.dev/models/db"
	"gitea.dev/modules/setting"
	"gitea.dev/modules/timeutil"
	"gitea.dev/modules/util"
)

var errWorkspaceRouteKeyRotationDenied = errors.New("Branchroom workspace route-key rotation denied")

// RotateRepositoryWorkspaceRouteKeyRequest identifies an owner-authorized
// incident-response rotation. The route key itself is generated by the service.
type RotateRepositoryWorkspaceRouteKeyRequest struct {
	RepoID    int64
	ScopeID   int64
	Actor     Actor
	Surface   branchroom_model.Surface
	RequestID string
}

// RotateRepositoryWorkspaceRouteKey replaces the opaque route key for one ready
// repository workspace. It records a stable workspace identity rather than either
// route key in the decision and audit stream.
func RotateRepositoryWorkspaceRouteKey(ctx context.Context, request RotateRepositoryWorkspaceRouteKeyRequest) error {
	if !setting.Branchroom.Enabled || request.RepoID <= 0 || request.ScopeID <= 0 || request.Actor.Type != branchroom_model.ActorTypeUser || request.Actor.ID <= 0 || !branchroom_model.IsSurfaceValid(request.Surface) {
		return workspaceRouteKeyRotationNotFound()
	}

	err := db.WithTx(ctx, func(txCtx context.Context) error {
		scope, err := requireActiveScopeTx(txCtx, request.RepoID, request.Actor, request.ScopeID, "Branchroom workspace does not exist")
		if err != nil {
			return workspaceRouteKeyRotationError(err)
		}

		workspace, err := branchroom_model.GetWorkspaceByScopeIDForUpdate(txCtx, scope.ID)
		if err != nil {
			return workspaceRouteKeyRotationError(err)
		}
		if workspace.Validate() != nil || workspace.ScopeID != scope.ID || workspace.RepoID != request.RepoID || workspace.State != branchroom_model.WorkspaceStateReady {
			return errWorkspaceRouteKeyRotationDenied
		}

		newRouteKey, err := branchroom_model.NewWorkspaceRouteKey()
		if err != nil {
			return err
		}
		rotated, err := branchroom_model.RotateWorkspaceRouteKey(txCtx, workspace, newRouteKey)
		if err != nil {
			return workspaceRouteKeyRotationError(err)
		}
		if !rotated {
			return errWorkspaceRouteKeyRotationDenied
		}

		now := timeutil.TimeStampNow()
		_, err = branchroom_model.RecordDecisionAndAudit(txCtx, scope, &branchroom_model.Decision{
			ScopeID:         scope.ID,
			RepoID:          scope.RepoID,
			ActorType:       request.Actor.Type,
			ActorID:         request.Actor.ID,
			Action:          branchroom_model.ActionManagePolicy,
			ResourceType:    branchroom_model.ResourceTypeWorkspace,
			ResourceID:      workspaceResourceID(workspace.WorkspaceKey),
			Surface:         request.Surface,
			Result:          branchroom_model.DecisionResultAllow,
			ReasonCode:      reasonWorkspaceRouteKeyRotated,
			OrdinaryAllowed: true,
			RequestID:       request.RequestID,
			ExpiresUnix:     now,
			CreatedUnix:     now,
		})
		return err
	})
	if errors.Is(err, errWorkspaceRouteKeyRotationDenied) {
		return workspaceRouteKeyRotationNotFound()
	}
	return err
}

func workspaceRouteKeyRotationError(err error) error {
	if errors.Is(err, util.ErrNotExist) || errors.Is(err, util.ErrInvalidArgument) {
		return errWorkspaceRouteKeyRotationDenied
	}
	return err
}

func workspaceRouteKeyRotationNotFound() error {
	return util.NewNotExistErrorf("Branchroom workspace does not exist")
}
